// Some portions generated by Codex
// Some portions generated by Claude
/** How many links of a node are loaded, which statements Expand skips, and how many are left to load. */
import type { Binding } from "./explorer-types.ts";
import { RDF_TYPE } from "./graph-canvas-scope.ts";
import { bindingsToTriples, tripleEdgeId } from "./graph-terms.ts";
import type { Graph } from "./graph-types.ts";
import { statementLinksOf } from "./statement-links.ts";
import { sparqlFacetValueToken, sparqlTermFromNodeId, isSafeSparqlIri } from "./rdf-terms.ts";
import type { LoadedLinks } from "./rdf-vocabulary.ts";

/**
 * The loaded links of every node as the canvas draws them and linkCountQuery counts them: statements between two
 * resources, types left out; a statement from a node to itself counts once in each direction.
 */
export function loadedLinkCounts(graph: Graph) {
  const literal = new Set(graph.nodes.flatMap((node) => (node.kind === "literal" ? [node.id] : [])));
  const counts = new Map<string, number>();
  for (const edge of graph.edges) {
    if (edge.predicate === RDF_TYPE || literal.has(edge.target)) continue;
    counts.set(edge.source, (counts.get(edge.source) ?? 0) + 1);
    counts.set(edge.target, (counts.get(edge.target) ?? 0) + 1);
  }
  return counts;
}

/**
 * Every loaded statement with reusable endpoints as SPARQL tokens, for Expand to skip. A document blank node (one
 * the repository did not certify) has no token, and comes back under a new identity in every answer; its predicates
 * are listed instead, so Expand leaves out the blank nodes it would only bring again as copies.
 */
export function loadedLinksOf(graph: Graph, ids: readonly string[]) {
  const wanted = new Set(ids);
  type Links = {
    outgoing: Array<[string, string]>;
    incoming: Array<[string, string]>;
    blankOutgoing?: string[];
    blankIncoming?: string[];
  };
  const loaded = new Map<string, Links>();
  const entry = (id: string) => {
    let links = loaded.get(id);
    if (!links) loaded.set(id, (links = { outgoing: [], incoming: [] }));
    return links;
  };
  const documentBlank = (id: string) => sparqlTermFromNodeId(id)?.type === "bnode";
  const addBlank = (links: Links, key: "blankOutgoing" | "blankIncoming", predicate: string) => {
    const predicates = (links[key] ??= []);
    if (!predicates.includes(predicate)) predicates.push(predicate);
  };
  for (const edge of graph.edges) {
    const predicate = isSafeSparqlIri(edge.predicate) ? `<${edge.predicate}>` : null;
    if (!predicate) continue;
    if (wanted.has(edge.source)) {
      const target = sparqlFacetValueToken(edge.target);
      if (target) entry(edge.source).outgoing.push([predicate, target]);
      else if (documentBlank(edge.target)) addBlank(entry(edge.source), "blankOutgoing", predicate);
    }
    if (wanted.has(edge.target)) {
      const source = sparqlFacetValueToken(edge.source);
      if (source) entry(edge.target).incoming.push([source, predicate]);
      else if (documentBlank(edge.source)) addBlank(entry(edge.target), "blankIncoming", predicate);
    }
  }
  return loaded as Map<string, LoadedLinks>;
}

/**
 * The links of a node that are not loaded yet, from the repository's count (which stops at `cap + 1`); null when
 * everything is loaded. Past the cap only a lower bound is known: "920+".
 */
export function moreLinks(total: number, loaded: number, cap: number) {
  const atLeast = total > cap;
  const count = atLeast ? cap + 1 - loaded : total - loaded;
  if (count <= 0) return null;
  return { count, atLeast, text: atLeast ? `${count}+` : `+${count}` };
}

/** A node's link count from the repository and the cap it was counted with (counting stops at `cap + 1`). */
export type LinkTotal = { count: number; cap: number };

/** The link-count query's own bound (linkCountQuery). */
const LINK_COUNT_CAP_BOUND = 100000;

/**
 * How far to count a node's links: `base` past the links of it the graph holds, so that the loaded links never use up
 * the count and a hub with many of them loaded still shows that it has more.
 */
export function linkCountCap(loaded: number, base: number) {
  return Math.min(LINK_COUNT_CAP_BOUND, base + Math.max(0, loaded));
}

/**
 * Whether a node's links must be counted (again): never counted, or counted only as far as the links the graph now
 * holds, so the count can no longer say whether there are more.
 */
export function linkTotalStale(total: LinkTotal | undefined, loaded: number) {
  return !total || (total.count > total.cap && loaded >= total.count);
}

/** The badge's text as words, for its tooltip and the node's accessible name: "12 more links". */
export function moreLinksPhrase(text: string) {
  const count = Number.parseInt(text.replace(/\D/g, ""), 10) || 0;
  const phrase = `${count.toLocaleString()} more ${count === 1 ? "link" : "links"}`;
  return text.endsWith("+") ? `at least ${phrase}` : phrase;
}

/** Whether an Expand answer holds a statement (or a statement about a statement) the graph does not have yet. */
export function bringsNewLinks(graph: Graph, bindings: readonly Binding[]) {
  const edges = new Set(graph.edges.map((edge) => tripleEdgeId(edge.source, edge.predicate, edge.target)));
  if (bindingsToTriples([...bindings]).some((triple) => !edges.has(tripleEdgeId(triple.source, triple.predicate, triple.target))))
    return true;
  const links = new Set((graph.statementLinks ?? []).map((link) => link.id));
  return statementLinksOf(bindings).some(({ link }) => !links.has(link.id));
}
